1	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
2	import { EdgeTracer, EdgeMetrics } from "../requisicao-automatica-ia/telemetry.ts";
3	
4	// Agente revisor (segunda opinião) dos matches da requisição MANUAL.
5	// Olha cada item já matcheado e, se PELO NOME outro produto do catálogo combina
6	// claramente melhor, sinaliza — não muda nada, só avisa o operador (Sim/Não na UI).
7	// Best-effort: qualquer falha retorna flags=[] sem quebrar o fluxo do frontend.
8	
9	const corsHeaders = {
10	  'Access-Control-Allow-Origin': '*',
11	  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-application, traceparent',
12	};
13	
14	// Mesmo chain barato do parser manual. Primário = gpt-4.1-mini: comprovadamente confiável
15	// p/ JSON estrito desta tarefa (grok-4.1-fast falhava e caía pro fallback, desperdiçando uma
16	// ida à API + latência). grok fica como fallback baratíssimo. Dispara o próximo em erro/vazio.
17	const FALLBACK_MODELS = [
18	  'deepseek/deepseek-v4-flash',
19	  'openai/gpt-4.1-mini',
20	  'x-ai/grok-4.1-fast',
21	  'google/gemini-2.5-flash',
22	  'qwen/qwen3-32b',
23	];
24	
25	const SYSTEM_PROMPT = `Você é um REVISOR de matches de produtos da MOMMA (doces artesanais).
26	
27	Recebe uma lista de [ITENS]. Cada item tem:
28	- "secao": o título/cabeçalho da seção a que o item pertence (ex.: "Bolos no Pote"). Pode vir vazio.
29	- "texto": o que o operador digitou (verbatim)
30	- "match": o produto ao qual o sistema associou esse texto
31	
32	E recebe o [CATÁLOGO] de produtos válidos (produtos_master).
33	
34	TAREFA: para cada item, decidir se o "match" está correto OU se, PELO NOME, outro
35	produto do catálogo combina CLARAMENTE melhor com o "texto".
36	
37	REGRAS:
38	- Seja CONSERVADOR. Só sinalize quando houver divergência CLARA. Ex.: texto "morango"
39	  matcheado como "Café em Grão", existindo "Bombom Morango" no catálogo.
40	- HERANÇA DE SEÇÃO (MUITO IMPORTANTE): o nome completo do produto = prefixo da "secao" + sabor
41	  do "texto". Se o "match" é de uma categoria DIFERENTE da "secao" — ex.: texto "chocolate" na
42	  seção "Bolos no Pote" matcheado como "Mini de Chocolate" — SINALIZE e sugira o produto da
43	  seção certa ("Bolo no Pote Chocolate"), se existir no [CATÁLOGO]. Ignore quando "secao" vier vazia.
44	- Se o match estiver plausível, NÃO sinalize.
45	- Variação ortográfica/abreviação normal do português NÃO é erro: "banoffe"="Banoffee",
46	  "cx"=caixa, "doce de leite"="Doce de Leite", plural/singular, acento. Ignore isso.
47	- "suggested_name" DEVE ser um nome EXATO existente no [CATÁLOGO]. Nunca invente.
48	- Considere o sabor/variante como sinal principal de correspondência.
49	
50	SAÍDA — JSON estrito, contendo SOMENTE os itens suspeitos (use o índice numérico do item):
51	{
52	  "flags": [
53	    { "index": 2, "suggested_name": "Bombom Morango", "reason": "texto 'morango' combina com Bombom Morango; match atual é de outra categoria" }
54	  ]
55	}
56	Se nenhum item for suspeito, retorne exatamente: { "flags": [] }
57	Não escreva nada fora do JSON.`;
58	
59	interface LlmResult {
60	  content: string;
61	  usage: { prompt_tokens?: number; completion_tokens?: number } | null;
62	}
63	
64	async function callModel(prompt: string, model: string): Promise<LlmResult> {
65	  const apiKey = Deno.env.get('OPENROUTER_API_KEY');
66	  if (!apiKey) throw new Error('OPENROUTER_API_KEY not set');
67	  const res = await fetch('https://openrouter.ai/api/v1/chat/completions', {
68	    method: 'POST',
69	    headers: {
70	      'Authorization': `Bearer ${apiKey}`,
71	      'Content-Type': 'application/json',
72	      'HTTP-Referer': 'https://momma-stock-insight.vercel.app',
73	      'X-Title': 'momma-match-review',
74	    },
75	    body: JSON.stringify({
76	      model,
77	      messages: [
78	        { role: 'system', content: SYSTEM_PROMPT },
79	        { role: 'user', content: prompt },
80	      ],
81	      temperature: 0,
82	      // Força JSON limpo (sem fences/preâmbulo) — melhora confiabilidade do modelo
83	      // primário (grok) e dos demais; o parse de fallback ainda cobre quem ignorar.
84	      response_format: { type: 'json_object' },
85	    }),
86	  });
87	  if (!res.ok) {
88	    const txt = await res.text().catch(() => '');
89	    throw new Error(`OpenRouter ${model}: ${res.status} ${txt}`);
90	  }
91	  const data = await res.json();
92	  return { content: data?.choices?.[0]?.message?.content ?? '', usage: data?.usage ?? null };
93	}
94	
95	async function callWithFallback(prompt: string): Promise<{ content: string; model: string; usage: LlmResult['usage'] }> {
96	  let lastErr: unknown;
97	  for (const model of FALLBACK_MODELS) {
98	    try {
99	      const { content, usage } = await callModel(prompt, model);
100	      if (content && content.trim()) return { content, model, usage };
101	    } catch (err) {
102	      lastErr = err;
103	      console.warn('[review] model fail', model, err instanceof Error ? err.message : String(err));
104	    }
105	  }
106	  throw lastErr || new Error('Todos os modelos de fallback falharam');
107	}
108	
109	function parseJson(content: string): unknown {
110	  let clean = content.trim();
111	  if (clean.startsWith('```')) {
112	    clean = clean.replace(/^```(?:json)?\s*/, '').replace(/\s*```$/, '');
113	  }
114	  return JSON.parse(clean);
115	}
116	
117	serve(async (req) => {
118	  if (req.method === 'OPTIONS') {
119	    return new Response(null, { headers: corsHeaders });
120	  }
121	
122	  const tracer = new EdgeTracer(req, { serviceName: 'gidape-edge-match-review' });
123	  const metrics = new EdgeMetrics({ serviceName: 'gidape-edge-match-review' });
124	  const rootSpan = tracer.startSpan('review-requisition-matches');
125	
126	  try {
127	    const { items, productCatalog } = await req.json();
128	    if (!Array.isArray(items) || items.length === 0) {
129	      rootSpan.end();
130	      Promise.all([tracer.flush(), metrics.flush()]).catch(() => {});
131	      return new Response(JSON.stringify({ flags: [] }), {
132	        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
133	      });
134	    }
135	    rootSpan.setAttribute('review.items', items.length);
136	
137	    const catalogLines = (Array.isArray(productCatalog) ? productCatalog : [])
138	      .slice(0, 300) // cap p/ evitar overflow de token
139	      .map((p: { name?: string }) => String(p?.name ?? '').trim())
140	      .filter(Boolean)
141	      .join('\n');
142	
143	    const itemLines = items
144	      .map(
145	        (it: { texto?: string; match?: string; categoria?: string }, i: number) =>
146	          `${i}. secao="${String(it?.categoria ?? '').replace(/"/g, "'")}" | texto="${String(it?.texto ?? '').replace(/"/g, "'")}" | match="${String(it?.match ?? '').replace(/"/g, "'")}"`,
147	      )
148	      .join('\n');
149	
150	    const prompt = `[ITENS]\n${itemLines}\n\n[CATÁLOGO]\n${catalogLines}`;
151	
152	    const llmSpan = tracer.startSpan('llm-call-openrouter', rootSpan.spanId);
153	    const llmStart = Date.now();
154	    const { content, model, usage } = await callWithFallback(prompt);
155	    const llmDurationMs = Date.now() - llmStart;
156	    llmSpan.setAttribute('llm.model', model);
157	    llmSpan.setAttribute('llm.provider', 'openrouter');
158	    if (usage) {
159	      const inputTokens = usage.prompt_tokens ?? 0;
160	      const outputTokens = usage.completion_tokens ?? 0;
161	      llmSpan.setAttribute('llm.usage.input_tokens', inputTokens);
162	      llmSpan.setAttribute('llm.usage.output_tokens', outputTokens);
163	      metrics.recordLlmCall({
164	        model,
165	        provider: 'openrouter',
166	        operation: 'match-review',
167	        inputTokens,
168	        outputTokens,
169	        durationMs: llmDurationMs,
170	      });
171	    }
172	    llmSpan.end();
173	
174	    let parsed: { flags?: unknown };
175	    try {
176	      parsed = parseJson(content) as { flags?: unknown };
177	    } catch {
178	      console.warn('[review] parse fail', content?.slice?.(0, 300));
179	      parsed = { flags: [] };
180	    }
181	    const flags = Array.isArray(parsed?.flags) ? parsed.flags : [];
182	    rootSpan.setAttribute('review.flags', flags.length);
183	    rootSpan.end();
184	    Promise.all([tracer.flush(), metrics.flush()]).catch(() => {});
185	
186	    return new Response(JSON.stringify({ flags, model }), {
187	      headers: { ...corsHeaders, 'Content-Type': 'application/json', 'traceparent': tracer.getResponseTraceparent() },
188	    });
189	  } catch (error) {
190	    console.error('[review] fatal', error);
191	    rootSpan.endWithError(error instanceof Error ? error.message : String(error));
192	    Promise.all([tracer.flush(), metrics.flush()]).catch(() => {});
193	    // Best-effort: nunca quebra o fluxo do frontend (review é opcional).
194	    return new Response(
195	      JSON.stringify({ flags: [], error: error instanceof Error ? error.message : String(error) }),
196	      { status: 200, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
197	    );
198	  }
199	});
