135	// ─── Alias Map (aprendizado de match) ──────────────────────────────────────
136	
137	/** Mapa de alias → produto_id para match por aprendizado. */
138	export interface AliasEntry {
139	  produto_id: number;
140	  alias: string;
141	}
142	
143	// ─── Auto-Enrichment (Match com catálogo) ───────────────────────────────────
144	
145	export interface EnrichmentResult {
146	  /** Itens mantidos na lista principal (matched). */
147	  keptItems: AIProcessedItem[];
148	  /** Itens movidos para revisão (unmatched). */
149	  reviewItems: AIProcessedItem[];
150	  /** Se houve alguma mudança. */
151	  hasChanges: boolean;
152	  /** Aliases usados neste enriquecimento (para incrementar used_count). */
153	  usedAliasIds: number[];
154	}
155	
156	/**
157	 * Enriquece itens fazendo match com o catálogo de produtos.
158	 * Prioridade: 1) já locked → manter, 2) match estrito por nome,
159	 * 3) match por alias (aprendizado), 4) fuzzy similarity.
160	 * Sem match → vai para revisão.
161	 */
162	export function enrichItemsWithCatalog(
163	  items: AIProcessedItem[],
164	  catalog: CatalogProduct[],
165	  threshold: number = MATCH_THRESHOLD,
166	  aliases: AliasEntry[] = []
167	): EnrichmentResult {
168	  if (catalog.length === 0 || items.length === 0) {
169	    return { keptItems: [...items], reviewItems: [], hasChanges: false, usedAliasIds: [] };
170	  }
171	
172	  const normalize = (s: string) => s.toLowerCase().trim();
173	  const catalogById = new Map(catalog.map(p => [p.id, p]));
174	
175	  // Indexar aliases: alias normalizado → produto
176	  const aliasMap = new Map<string, CatalogProduct>();
177	  for (const a of aliases) {
178	    const prod = catalogById.get(a.produto_id);
179	    if (prod) aliasMap.set(normalize(a.alias), prod);
180	  }
181	
182	  let hasChanges = false;
183	  const keptItems: AIProcessedItem[] = [];
184	  const reviewItems: AIProcessedItem[] = [];
185	  const usedAliasIds: number[] = [];
186	
187	  for (const item of items) {
188	    // 1) Itens já locked/coded são mantidos
189	    if (item.code && item.isLocked && item.matchedId) {
190	      keptItems.push(item);
191	      continue;
192	    }
193	
194	    const itemNorm = normalize(item.name);
195	
196	    // 2) Match estrito por nome no catálogo
197	    let match = catalog.find(p => normalize(p.nome) === itemNorm);
198	    let bestScore = 1;
199	    let matchSource: 'exact' | 'alias' | 'fuzzy' = 'exact';
200	
201	    // 3) Match por alias (aprendizado) — se não houve match estrito
202	    if (!match) {
203	      const aliasMatch = aliasMap.get(itemNorm);
204	      if (aliasMatch) {
205	        match = aliasMatch;
206	        bestScore = 1;
207	        matchSource = 'alias';
208	        const aliasEntry = aliases.find(a => normalize(a.alias) === itemNorm);
209	        if (aliasEntry) usedAliasIds.push(aliasEntry.produto_id);
210	      }
211	    }
212	
213	    // 4) Match fuzzy se nenhum anterior achou
214	    if (!match) {
215	      let bestMatch: CatalogProduct | null = null;
216	      let bestSim = 0;
217	      for (const p of catalog) {
218	        const sim = similarity(item.name, p.nome);
219	        if (sim > bestSim) {
220	          bestSim = sim;
221	          bestMatch = p;
222	        }
223	      }
224	      if (bestMatch && bestSim >= threshold) {
225	        match = bestMatch;
226	        bestScore = bestSim;
227	        matchSource = 'fuzzy';
228	      }
229	    }
230	
231	    if (match) {
232	      hasChanges = true;
233	      keptItems.push({
234	        ...item,
235	        name: match.nome,
236	        code: match.codigo_interno,
237	        matchedId: match.id.toString(),
238	        category: match.categoria_nome || item.category,
239	        manualCategory: match.categoria_nome || item.manualCategory,
240	        isLocked: true,
241	        matchConfidence: bestScore,
242	        isLowConfidence: false,
243	        originalName: matchSource !== 'exact' ? item.name : undefined,
244	      });
245	    } else {
246	      hasChanges = true;
247	      reviewItems.push({
248	        ...item,
249	        isLowConfidence: true,
250	        originalName: item.name,
251	      });
252	    }
253	  }
254	
255	  return { keptItems, reviewItems, hasChanges, usedAliasIds };
256	}
