381	/** Formata data no padrão brasileiro (dd/MM/yyyy HH:mm), timezone São Paulo. */
382	export function formatDateTimeBr(value?: string | null): string {
383	  if (!value) return '';
384	  const d = new Date(value);
385	  if (isNaN(d.getTime())) return '';
386	  return new Intl.DateTimeFormat('pt-BR', {
387	    day: '2-digit', month: '2-digit', year: 'numeric',
