2329	  function appendOverlap(buffer: string, chunk: string): string {
2330	    if (!buffer) return chunk;
2331	    const max = Math.min(buffer.length, 256);
2332	    for (let k = max; k > 0; k--) {
2333	      if (buffer.slice(-k) === chunk.slice(0, k)) {
2334	        return buffer + chunk.slice(k);
2335	      }
2336	    }
2337	    return buffer + chunk;
2338	  }
