2340	  function normalizeStreamText(input: string): string {
2341	    let text = input.replace(/\r\n/g, "\n");
2342	    text = text.replace(/\*+/g, "");
2343	    text = text.replace(/"+/g, "");
2344	    text = text.replace(/[^\S\n]+/g, " ");
2345	    const dense = (() => {
2346	      const noSpaceLen = text.replace(/\s+/g, '').length;
2347	      const spaceCount = text.length - noSpaceLen;
2348	      return text.length > 30 && (spaceCount < text.length * 0.05 || /[A-Za-zÀ-ÿ]{15,}/.test(text));
2349	    })();
2350	    if (dense) {
2351	      try {
2352	        const seg = new (Intl as any).Segmenter('pt', { granularity: 'word' });
2353	        const arr = Array.from(seg.segment(text)) as any[];
2354	        let rebuilt = '';
2355	        for (let i = 0; i < arr.length; i++) {
2356	          const cur = arr[i];
2357	          const prev = arr[i - 1];
2358	          if (i > 0 && prev?.isWordLike && cur.isWordLike) rebuilt += ' ';
2359	          rebuilt += cur.segment;
2360	        }
2361	        text = rebuilt;
2362	      } catch { }
2363	    }
2364	    text = text.replace(/\n{3,}/g, "\n\n");
2365	    text = text.replace(/\s*:\s*/g, ": ");
2366	    text = text.replace(/\s*,\s*/g, ", ");
2367	    text = text.replace(/\s*\.\s*/g, ". ");
2368	    text = text.replace(/ {2,}/g, " ").trim();
2369	    try {
2370	      const wordDedup = new RegExp('(\\b[\\p{L}0-9]+\\b)(?:\\s+\\1)+', 'gu');
2371	      text = text.replace(wordDedup, '$1');
2372	    } catch { }
2373	    return text;
2374	  }
2375	
2376	  function mergeStreamText(prev: string, chunk: string): string {
2377	    const cleaned = normalizeStreamText(chunk);
2378	    const merged = appendOverlap(prev, cleaned);
2379	    return normalizeStreamText(merged);
2380	  }
